import React, { useRef, useEffect } from 'react';

const GlobalParticles = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        let animationFrameId;
        let particles = [];

        // Configuration
        const particleCount = 200;
        const perspective = 800;
        const speed = 0.5; // Slower drift
        // DARKER COLOR for visibility on White Background
        const color = 'rgba(0, 120, 150, 0.9)'; // Darker, more opaque cyan

        // Mouse State
        let mouseX = 0;
        let mouseY = 0;
        let targetMouseX = 0;
        let targetMouseY = 0;

        // Resize canvas
        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
            centerX = canvas.width / 2;
            centerY = canvas.height / 2;
        };

        let centerX = window.innerWidth / 2;
        let centerY = window.innerHeight / 2;

        const handleMouseMove = (e) => {
            // Normalize mouse (-1 to 1)
            targetMouseX = (e.clientX - centerX) / centerX;
            targetMouseY = (e.clientY - centerY) / centerY;
        };

        window.addEventListener('resize', resize);
        window.addEventListener('mousemove', handleMouseMove);
        resize();

        // Particle class representing a point in 3D space
        class Particle3D {
            constructor() {
                this.reset(true);
            }

            reset(randomZ = false) {
                // Random position in 3D space relative to center
                // Range: -3000 to 3000 for X and Y covers wider field
                this.x = (Math.random() - 0.5) * 4000;
                this.y = (Math.random() - 0.5) * 4000;

                // Z: 0 is camera, larger is further away
                this.z = randomZ ? Math.random() * 2000 : 2000;

                this.size = Math.random() * 4 + 2; // Much Larger particles (2-6px)
                this.opacity = Math.random() * 0.4 + 0.6; // Higher minimum opacity (0.6-1.0)

                // Add base drift so it moves without mouse
                this.baseVx = (Math.random() - 0.5) * 2;
                this.baseVy = (Math.random() - 0.5) * 2;
            }

            update() {
                // Move towards camera
                this.z -= speed;

                // Intrinsic Movement (Always moving)
                this.x += this.baseVx;
                this.y += this.baseVy;

                // Mouse Interaction: "Antigravity" Parallax / Sway
                // HUGE multiplier for obvious effect
                this.x += (mouseX * 150);
                this.y += (mouseY * 150);

                // If behind camera, reset to back
                if (this.z <= 0) {
                    this.reset(false);
                    // Respread x/y to avoid clumping
                    this.x = (Math.random() - 0.5) * 4000;
                    this.y = (Math.random() - 0.5) * 4000;
                }
            }

            draw() {
                if (this.z <= 0) return;

                const scale = perspective / this.z;
                const screenX = centerX + this.x * scale;
                const screenY = centerY + this.y * scale;

                // Optimization: Skip off-screen rendering
                if (screenX < -50 || screenX > canvas.width + 50 ||
                    screenY < -50 || screenY > canvas.height + 50) return;

                const screenRadius = this.size * scale;
                const depthAlpha = 1 - (this.z / 2000);

                if (depthAlpha > 0) {
                    ctx.beginPath();
                    ctx.arc(screenX, screenY, screenRadius, 0, Math.PI * 2);

                    // Simple opacity calculation
                    ctx.fillStyle = color.replace('0.9', (this.opacity * depthAlpha).toFixed(2));
                    ctx.fill();
                }
            }
        }

        // Initialize particles
        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle3D());
        }

        // Animation loop
        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height); // Standard clear

            // Smooth mouse interpolation (Ease-out)
            mouseX += (targetMouseX - mouseX) * 0.05;
            mouseY += (targetMouseY - mouseY) * 0.05;

            particles.forEach(p => {
                p.update();
                p.draw();
            });

            animationFrameId = requestAnimationFrame(animate);
        };

        animate();

        return () => {
            window.removeEventListener('resize', resize);
            window.removeEventListener('mousemove', handleMouseMove);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            className="global-particles"
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                width: '100vw',
                height: '100vh',
                pointerEvents: 'none',
                zIndex: 9999, // Force ON TOP
                mixBlendMode: 'multiply' // Good for dark particles on white bg
            }}
        />
    );
};

export default GlobalParticles;

import React, { useEffect, useRef } from 'react';

const HeroBackground = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        let animationFrameId;

        const resize = () => {
            const parent = canvas.parentElement;
            if (parent) {
                canvas.width = parent.clientWidth;
                canvas.height = parent.clientHeight;
            }
        };

        window.addEventListener('resize', resize);
        resize();

        // Premium Dark Gradient Mesh (Deep Navy/Slate Base)
        // Using distinct "Glacier" colors: Cyan, Sky Blue, Deep Violet mixed with Slate
        const colors = [
            { r: 15, g: 23, b: 42 },   // Slate 900 (Base)
            { r: 8, g: 145, b: 178 },  // Cyan 600
            { r: 79, g: 70, b: 229 },  // Indigo 600
            { r: 15, g: 118, b: 110 }  // Teal 700 (Deep accent)
        ];

        let time = 0;

        const draw = () => {
            time += 0.002;
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Create a rich mesh gradient
            const w = canvas.width;
            const h = canvas.height;

            const gradient = ctx.createLinearGradient(0, 0, w, h);
            gradient.addColorStop(0, '#1e293b'); // Slate 800 (Lighter base)
            gradient.addColorStop(1, '#334155'); // Slate 700 (Twilight)

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, w, h);

            // Add moving ambient orbs for depth (Brighter opacity)
            const orbs = [
                { x: w * 0.2, y: h * 0.3, r: h * 0.6, color: 'rgba(56, 189, 248, 0.20)' }, // Sky (brighter)
                { x: w * 0.8, y: h * 0.7, r: h * 0.5, color: 'rgba(99, 102, 241, 0.15)' }, // Indigo (brighter)
                { x: w * 0.5, y: h * 0.5, r: h * 0.4, color: 'rgba(20, 184, 166, 0.12)' } // Teal (brighter)
            ];

            orbs.forEach((orb, i) => {
                const floatX = Math.sin(time + i) * 50;
                const floatY = Math.cos(time + i * 0.5) * 50;

                const g = ctx.createRadialGradient(
                    orb.x + floatX, orb.y + floatY, 0,
                    orb.x + floatX, orb.y + floatY, orb.r
                );
                g.addColorStop(0, orb.color);
                g.addColorStop(1, 'transparent');

                ctx.fillStyle = g;
                ctx.beginPath();
                ctx.arc(orb.x + floatX, orb.y + floatY, orb.r, 0, Math.PI * 2);
                ctx.fill();
            });

            animationFrameId = requestAnimationFrame(draw);
        };

        draw();

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            className="neural-background"
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                zIndex: 0,
                pointerEvents: 'none'
            }}
        />
    );
};

export default HeroBackground;

import React, { useEffect, useRef } from 'react';

const MatrixRain = () => {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');

        // Set canvas size
        const resize = () => {
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;
        };
        window.addEventListener('resize', resize);
        resize();

        // Configuration
        const fontSize = 14;
        const columns = canvas.width / fontSize;
        const drops = []; // Array of drops - one per column

        // Initialize drops at random y positions for natural start
        for (let i = 0; i < columns; i++) {
            drops[i] = Math.random() * -100;
        }

        // Neo-Cyan Palette (Matches project theme)
        const colors = ['#0ee919ff', '#22D3EE', '#000000'];
        // We will use a gradient or just bright cyan

        const chars = "XYZ01010101AI_MODELS_VISION_ARCH_SYSTEM_DEPLOY_NEURAL_NET";
        const charArray = chars.split('');

        const draw = () => {
            // Translucent black background for trail effect
            ctx.fillStyle = 'rgba(255, 255, 255, 0.1)'; // White fade for light theme
            // Actually, for a white background landing page, Matrix rain is tricky.
            // We need a subtle "Data Stream" look.

            // Let's stick to the Dark Theme or ensure this works on White.
            // The current landing page is Light/White themed based on previous context ("white background without blocking clicks").
            // "Matrix" usually needs dark bg.
            // Let's do "Digital Rain" in Cyan on White.

            ctx.fillStyle = 'rgba(255, 255, 255, 0.2)'; // Fade out previous frame
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.font = `${fontSize}px monospace`;

            for (let i = 0; i < drops.length; i++) {
                // Random char
                const text = charArray[Math.floor(Math.random() * charArray.length)];

                // Color: Dark Cyan for visibility on white
                ctx.fillStyle = '#0891b2'; // Cyan-600

                // Occasional "Glitch" color
                if (Math.random() > 0.98) ctx.fillStyle = '#0ea5e9'; // Sky-500

                ctx.fillText(text, i * fontSize, drops[i] * fontSize);

                // Reset drop to top randomly
                if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
                    drops[i] = 0;
                }

                // Move drop down
                drops[i]++;
            }
        };

        const interval = setInterval(draw, 33);

        return () => {
            clearInterval(interval);
            window.removeEventListener('resize', resize);
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                zIndex: 0, // Behind content but visible
                pointerEvents: 'none',
                opacity: 0.3 // Subtle but visible
            }}
        />
    );
};

