            <div style={{ padding: '4px 6px', fontSize: '0.65rem', fontWeight: '600', color: TOKENS.colors.text, textAlign: 'center', borderTop: '1px solid #F1F5F9' }}>
                {template.name}
            </div>
        </div>
    );
};

// Helper to safely fetch images avoiding CORS blocks on S3/Cloudfront
const fetchImageSafe = async (imageUrl) => {
    // Bypass browser cache which may have stored the image without CORS headers from a standard <img> tag
    const cacheBustedUrl = imageUrl.includes('?') 
        ? `${imageUrl}&cors_t=${Date.now()}` 
        : `${imageUrl}?cors_t=${Date.now()}`;
        
    try {
        const res = await fetch(cacheBustedUrl, { mode: 'cors' });
        if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
        return await res.blob();
    } catch (e) {
        console.warn('Direct fetch failed (likely CORS), trying primary proxy for:', imageUrl);
        try {
            // Primary proxy
            const proxyUrl1 = `https://corsproxy.io/?url=${encodeURIComponent(imageUrl)}`;
            const res1 = await fetch(proxyUrl1);
            if (!res1.ok) throw new Error(`Proxy 1 HTTP error! status: ${res1.status}`);
            return await res1.blob();
        } catch (e2) {
            console.warn('Primary proxy failed, trying secondary proxy for:', imageUrl);
            // Secondary proxy
            const proxyUrl2 = `https://api.allorigins.win/raw?url=${encodeURIComponent(imageUrl)}`;
            const res2 = await fetch(proxyUrl2);
            if (!res2.ok) throw new Error(`Proxy 2 HTTP error! status: ${res2.status}`);
            return await res2.blob();
        }
    }
};

const URLImage = ({ imageElem, shapeProps, isSelected, onSelect, onChange }) => {
    const shapeRef = useRef();
    const trRef = useRef();
    const [image, setImage] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    
    useEffect(() => {
        let isMounted = true;
        let objectUrl = null;

        const loadImg = async () => {
            try {
                const blob = await fetchImageSafe(imageElem.url);
                if (!isMounted) return;
                
                objectUrl = window.URL.createObjectURL(blob);
                const img = new window.Image();
                img.src = objectUrl;
                img.onload = () => {
                    if (isMounted) {
                        setImage(img);
                        setIsLoading(false);
                        
                        if (!shapeProps.naturalWidth) {
                            const nW = img.naturalWidth || 1;
                            const nH = img.naturalHeight || 1;
                            const imgRatio = nW / nH;
                            
                            // Use existing slot dimensions as the container bounds
                            const containerW = shapeProps.width || 300;
                            const containerH = shapeProps.height || 300;
                            const containerRatio = containerW / containerH;
                            
                            // Object-fit: contain within the slot
                            let fitW, fitH;
                            if (imgRatio > containerRatio) {
                                fitW = containerW;
                                fitH = containerW / imgRatio;
                            } else {
                                fitH = containerH;
                                fitW = containerH * imgRatio;
                            }
                            
                            // Center within original slot bounds
                            const xOffset = (containerW - fitW) / 2;
                            const yOffset = (containerH - fitH) / 2;
                            
                            onChange({
                                ...shapeProps,
                                naturalWidth: nW,
                                naturalHeight: nH,
                                x: (shapeProps.x || 0) + xOffset,
                                y: (shapeProps.y || 0) + yOffset,
                                width: Math.max(50, fitW),
                                height: Math.max(50, fitH),
                            });
                        }
                    }
                };
            } catch (err) {
                console.error("Failed to load image for canvas:", err);
                if (isMounted) setIsLoading(false);
            }
        };

        loadImg();

        return () => {
            isMounted = false;
            if (objectUrl) {
                window.URL.revokeObjectURL(objectUrl);
            }
        };
    }, [imageElem.url]);

    useEffect(() => {
        if (isSelected && trRef.current && image) {
            trRef.current.nodes([shapeRef.current]);
            trRef.current.getLayer().batchDraw();
        }
    }, [isSelected, image]);

    if (!image) {
        // Return invisible placeholder while loading blob
        return (
            <Rect 
                {...shapeProps} 
                fill="#E2E8F0"
                stroke="#CBD5E1"
                strokeWidth={2}
                dash={[5, 10]}
            />
        );
    }

    return (
        <React.Fragment>
            <KonvaImage
                onClick={onSelect}
                onTap={onSelect}
                ref={shapeRef}
                {...shapeProps}
                image={image}
                draggable
                onDragEnd={(e) => {
                    onChange({
                        ...shapeProps,
                        x: e.target.x(),
                        y: e.target.y(),
                    });
                }}
                onTransformEnd={(e) => {
                    const node = shapeRef.current;
                    const scaleX = node.scaleX();
                    const scaleY = node.scaleY();
                    node.scaleX(1);
                    node.scaleY(1);
                    onChange({
                        ...shapeProps,
                        x: node.x(),
                        y: node.y(),
                        rotation: node.rotation(),
                        // Retain original crop ratio via transform
                        width: Math.max(5, node.width() * scaleX),
                        height: Math.max(5, node.height() * scaleY),
                    });
                }}
            />
            {isSelected && (
                <Transformer
                    ref={trRef}
                    keepRatio={false} // Allow free stretching
                    boundBoxFunc={(oldBox, newBox) => {
                        if (newBox.width < 20 || newBox.height < 20) {
                            return oldBox;
                        }
                        return newBox;
                    }}
                />
            )}
        </React.Fragment>
    );
};


const CollageManager = ({ initialPhotos = [], onClose, backLabel = "Back" }) => {
    const [images, setImages] = useState([]);
    const [availablePhotos, setAvailablePhotos] = useState([]);
    const [selectedId, setSelectedId] = useState(null);
    const [isExporting, setIsExporting] = useState(false);
    const [scale, setScale] = useState(0.5); // Dynamic zoom scale for the viewer
    const [gap, setGap] = useState(20);
    const [activeLayoutCols, setActiveLayoutCols] = useState(null);
    const stageRef = useRef(null);
    const containerRef = useRef(null);
    const { addToast } = useToast();

    // Auto layout pure function
    const applyGridLayout = useCallback((cols, gapSize, currentImages) => {
        if (currentImages.length === 0) return currentImages;
        const totalGapX = (cols + 1) * gapSize;
        const widthPerCell = (CANVAS_WIDTH - totalGapX) / cols;
        const rows = Math.ceil(currentImages.length / cols);
        const totalGapY = (rows + 1) * gapSize;
        const heightPerCell = (CANVAS_HEIGHT - totalGapY) / Math.max(rows, 1);

        return currentImages.map((img, i) => {
            const col = i % cols;
            const row = Math.floor(i / cols);
            
            let drawW = widthPerCell;
            let drawH = heightPerCell;
            
            if (img.naturalWidth && img.naturalHeight) {
                const imgRatio = img.naturalWidth / img.naturalHeight;
                const cellRatio = widthPerCell / heightPerCell;
                if (imgRatio > cellRatio) {
                    drawH = widthPerCell / imgRatio;
                } else {
                    drawW = heightPerCell * imgRatio;
                }
            }

            const xOffset = (widthPerCell - drawW) / 2;
            const yOffset = (heightPerCell - drawH) / 2;

            return {
                ...img,
                x: gapSize + col * (widthPerCell + gapSize) + xOffset,
                y: gapSize + row * (heightPerCell + gapSize) + yOffset,
                width: Math.max(10, drawW),
                height: Math.max(10, drawH),
                rotation: 0
            };
        });
    }, []);

    const handleAutoLayoutSelected = (layoutType) => {
        let cols = 2;
        if (layoutType === 'grid3') cols = 3;
        if (layoutType === 'grid4') cols = 4;
        
        setActiveLayoutCols(cols);
        setImages(prev => applyGridLayout(cols, gap, prev));
        setSelectedId(null);
    };

    // Load initial photos on mount
    useEffect(() => {
        const initialValid = initialPhotos.filter(p => !!p).map(url => ({
            id: uuidv4(),
            url: typeof url === 'string' ? url : (url.photo_url || url.url)
        }));
        setAvailablePhotos(initialValid);
        
        // Start with an empty canvas so the user can select exactly what they want
        setImages([]);
    }, [initialPhotos]);

    // Fit canvas scale to window perfectly
    useEffect(() => {
        const resize = () => {
            if (!containerRef.current) return;
            const containerWidth = containerRef.current.clientWidth;
            const containerHeight = containerRef.current.clientHeight;
            // Pad by 40px
            const scaleW = (containerWidth - 80) / CANVAS_WIDTH;
            const scaleH = (containerHeight - 80) / CANVAS_HEIGHT;
            setScale(Math.min(scaleW, scaleH));
        };
        resize();
        window.addEventListener('resize', resize);
        return () => window.removeEventListener('resize', resize);
    }, []);

    // Selection helpers
    const checkDeselect = (e) => {
        const clickedOnEmpty = e.target === e.target.getStage();
        if (clickedOnEmpty) setSelectedId(null);
    };

    // Keyboard deletions
    useEffect(() => {
        const onKey = (e) => {
            if ((e.key === 'Backspace' || e.key === 'Delete') && selectedId) {
                setImages(imgs => imgs.filter(img => img.id !== selectedId));
                setSelectedId(null);
            }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [selectedId]);


    // Layer manipulation logic
    const bringToFront = () => {
        if (!selectedId) return;
        const items = images.slice();
        const item = items.find(i => i.id === selectedId);
        const index = items.indexOf(item);
        if (index < items.length - 1) {
            items.splice(index, 1);
            items.push(item);
            setImages(items);
        }
    };
    
    const sendToBack = () => {
        if (!selectedId) return;
        const items = images.slice();
        const item = items.find(i => i.id === selectedId);
        const index = items.indexOf(item);
        if (index > 0) {
            items.splice(index, 1);
            items.unshift(item);
            setImages(items);
        }
    };

    const handleDelete = () => {
        if (!selectedId) return;
        setImages(images.filter(img => img.id !== selectedId));
        setSelectedId(null);
    }

    const togglePhoto = (photo) => {
        const exists = images.find(img => img.id === photo.id);
        if (exists) {
            setImages(images.filter(img => img.id !== photo.id));
            if (selectedId === photo.id) setSelectedId(null);
        } else {
            // Add to center
            const staggerX = (Math.random() * 100) - 50;
            const staggerY = (Math.random() * 100) - 50;
            const newImg = {
                id: photo.id,
                url: photo.url,
                x: (CANVAS_WIDTH / 2) - 150 + staggerX,
                y: (CANVAS_HEIGHT / 2) - 150 + staggerY,
                width: 300,
                height: 300,
                rotation: 0
            };
            setImages(prev => [...prev, newImg]);
            setSelectedId(photo.id);
            setActiveLayoutCols(null); // Custom addition breaks auto layout grid
        }
    };

    const applyTemplate = (template) => {
        const imageSlots = template.layers.filter(l => l.type === 'image');
        const textSlots  = template.layers.filter(l => l.type === 'text');
        
        // Map available photos into the image slots sequentially
        const newImages = imageSlots.map((slot, i) => {
            // Cycle through available photos if we have fewer than slots
            const photo = availablePhotos.length > 0 
                ? availablePhotos[i % availablePhotos.length] 
                : null;
            
            return {
                id: photo ? photo.id : uuidv4(),
                url: photo ? photo.url : '',
                x: slot.x,
                y: slot.y,
                width: slot.width,
                height: slot.height,
                rotation: 0,
                isTemplateSlot: true,
            };
        }).filter(img => img.url); // Only include ones with actual photos

        // Add text layers as special entries
        const textImages = textSlots.map(slot => ({
            id: uuidv4(),
            type: 'text',
            text: slot.text,
            fontSize: slot.fontSize || 24,
            fontStyle: slot.fontStyle || 'normal',
            fill: slot.fill || '#1E293B',
            x: slot.x,
            y: slot.y,
            rotation: 0,
        }));

        setImages([...newImages, ...textImages]);
        setSelectedId(null);
        setActiveLayoutCols(null);
    };

    const applyCrop = (ratioType) => {
        if (!selectedId) return;
        const items = images.slice();
        const idx = items.findIndex(i => i.id === selectedId);
        if (idx === -1) return;

        const img = { ...items[idx] };
        if (!img.naturalWidth || !img.naturalHeight) return;

        const nW = img.naturalWidth;
        const nH = img.naturalHeight;
        let crop = undefined;
        let newW = img.width;
        let newH = img.height;

        if (ratioType === 'reset') {
            crop = undefined;
            // Best effort to restore natural layout
            newH = img.width / (nW / nH);
        } else {
            let targetRatio = 1; // square
            if (ratioType === 'portrait') targetRatio = 4 / 5;
            if (ratioType === 'landscape') targetRatio = 16 / 9;

            const imageRatio = nW / nH;
            let cropW = nW;
            let cropH = nH;

            // Fit crop box completely inside natural image bounds
            if (imageRatio > targetRatio) {
                cropW = nH * targetRatio;
                cropH = nH;
            } else {
                cropH = nW / targetRatio;
                cropW = nW;
            }

            crop = {
                x: (nW - cropW) / 2, // Center crop perfectly
                y: (nH - cropH) / 2,
                width: cropW,
                height: cropH
            };

            // Shape visual canvas box to match this perfect new ratio
            newH = img.width / targetRatio;
        }

        items[idx] = { ...img, crop, width: newW, height: newH };
        setImages(items);
        setActiveLayoutCols(null);
    };

    const handleExport = () => {
        if (!stageRef.current) return;
        setIsExporting(true);
        setSelectedId(null); // Clear selection rings for export

        // Provide brief delay for transformer rings to vanish
        setTimeout(() => {
            try {
                // Native Konva high-res export (bypassing any DOM css issues)
                const dataURL = stageRef.current.toDataURL({ 
                    pixelRatio: 2, 
                    mimeType: 'image/jpeg', 
                    quality: 1 
                });
                saveAs(dataURL, `Photo-Collage-${Date.now()}.jpg`);
                addToast("Collage exported successfully!", "success");
            } catch (err) {
                console.error("Export failed:", err);
                addToast("Failed to export. Ensure all images have loaded successfully.", "error");
            } finally {
                setIsExporting(false);
            }
        }, 150);
    };

    return (
        <div style={{
            position: 'fixed', inset: 0, zIndex: 2000,
            background: TOKENS.colors.background,
            display: 'flex', flexDirection: 'column',
            fontFamily: '"Inter", -apple-system, sans-serif',
            color: TOKENS.colors.text,
            overflow: 'hidden'
        }}>
            {/* Header */}
            <header style={{
                padding: '1rem',
                backgroundColor: 'rgba(255, 255, 255, 0.9)',
                backdropFilter: 'blur(12px)',
                borderBottom: `1px solid ${TOKENS.colors.border}`,
                display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'center',
                gap: '0.75rem',
                boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
                zIndex: 10,
                flexShrink: 0
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                    <button
                        onClick={onClose}
                        style={{
                            background: 'white', border: `1px solid ${TOKENS.colors.border}`,
                            color: TOKENS.colors.text, cursor: 'pointer',
                            display: 'flex', alignItems: 'center', gap: '0.5rem',
                            fontSize: '0.9rem', fontWeight: '600',
                            padding: '0.5rem 1rem', borderRadius: '8px',
                            transition: 'all 0.2s', boxShadow: '0 1px 2px rgba(0,0,0,0.05)'
                        }}
                    >
                        <ArrowLeft size={18} /> {backLabel}
                    </button>
                    <div style={{ width: '1px', height: '24px', background: TOKENS.colors.border }} />
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                        <div style={{
                            width: '32px', height: '32px', borderRadius: '8px',
                            background: '#EEF2FF', color: TOKENS.colors.primary,
                            display: 'flex', alignItems: 'center', justifyContent: 'center'
                        }}>
                            <Layers size={18} />
                        </div>
                        <h2 style={{ fontSize: '1.25rem', fontWeight: '700', margin: 0, color: TOKENS.colors.text }}>Interactive Canvas Editor</h2>
                    </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: '1rem' }}>
                    <button
                        onClick={handleExport}
                        style={{
                            display: 'flex', alignItems: 'center', gap: '0.5rem',
                            padding: '0.6rem 1.25rem', borderRadius: '8px',
                            background: `linear-gradient(135deg, ${TOKENS.colors.primary} 0%, ${TOKENS.colors.primaryHover} 100%)`,
                            border: 'none', color: 'white', fontWeight: '600', cursor: 'pointer',
                            boxShadow: '0 4px 6px -1px rgba(79, 70, 229, 0.2)',
                            fontSize: '0.9rem',
                        }}
                    >
                        {isExporting ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
                        {isExporting ? 'Exporting HD...' : 'Export High-Res JPG'}
                    </button>
                </div>
            </header>

            {/* Main Editor Content */}
            <div style={{ flex: 1, display: 'flex', overflow: 'hidden' }}>

                {/* Left Sidebar Toolbar */}
                <div style={{
                    width: '300px', background: TOKENS.colors.surface, borderRight: `1px solid ${TOKENS.colors.border}`,
                    padding: '1.5rem', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '2rem',
                    zIndex: 20, flexShrink: 0
                }}>
                    
                    {/* Object Controls Tools */}
                    <div>
                        <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, marginBottom: '1rem', fontWeight: '700' }}>Active Photo Tools</h3>
                        
                        <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                            <button onClick={bringToFront} disabled={!selectedId} style={{ flex: 1, ...btnStyle(!!selectedId) }}>
                                <BringToFront size={16} /> Front
                            </button>
                            <button onClick={sendToBack} disabled={!selectedId} style={{ flex: 1, ...btnStyle(!!selectedId) }}>
                                <SendToBack size={16} /> Back
                            </button>
                        </div>
                        <button onClick={handleDelete} disabled={!selectedId} style={{ width: '100%', marginTop: '0.5rem', background: selectedId ? '#FEE2E2' : '#F1F5F9', color: selectedId ? '#EF4444' : '#94A3B8', border: 'none', padding: '0.75rem', borderRadius: '8px', cursor: selectedId ? 'pointer' : 'not-allowed', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.5rem', fontWeight: '600' }}>
                            <Trash2 size={16} /> Delete Photo
                        </button>
                        
                        {/* Crop Tools */}
                        <div style={{ marginTop: '1.5rem', opacity: selectedId ? 1 : 0.5, pointerEvents: selectedId ? 'auto' : 'none' }}>
                            <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, marginBottom: '0.75rem', fontWeight: '700', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                                <Crop size={14} /> Crop Shape
                            </h3>
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.5rem' }}>
                                <button onClick={() => applyCrop('square')} style={btnStyle(false)}>
                                    <Square size={16} /> 1:1
                                </button>
                                <button onClick={() => applyCrop('portrait')} style={btnStyle(false)}>
                                    <RectangleVertical size={16} /> 4:5
                                </button>
                                <button onClick={() => applyCrop('landscape')} style={btnStyle(false)}>
                                    <RectangleHorizontal size={16} /> 16:9
                                </button>
                                <button onClick={() => applyCrop('reset')} style={btnStyle(false)}>
                                    <RotateCcw size={16} /> Reset
                                </button>
                            </div>
                        </div>

                        {!selectedId && <p style={{ fontSize: '0.75rem', color: TOKENS.colors.textDim, marginTop: '1rem', textAlign: 'center' }}>Click a photo on the canvas to select it for editing.</p>}
                    </div>

                    <hr style={{ border: 'none', borderTop: `1px solid ${TOKENS.colors.border}` }} />
                    
                    {/* Auto Layout Setters */}
                    <div>
                        <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, marginBottom: '1rem', fontWeight: '700' }}>Auto-Grid Layouts</h3>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                            <button className="layout-btn" onClick={() => handleAutoLayoutSelected('grid2')} style={layoutBtnStyle}>
                                <Layout size={20} /> 2 Col
                            </button>
                            <button className="layout-btn" onClick={() => handleAutoLayoutSelected('grid3')} style={layoutBtnStyle}>
                                <LayoutGrid size={20} /> 3 Col
                            </button>
                        </div>

                        <div style={{ marginTop: '1.5rem' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                                <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, margin: 0, fontWeight: '700' }}>Generation Gap</h3>
                                <span style={{ fontSize: '0.8rem', fontWeight: '600', color: TOKENS.colors.primary }}>{gap}px</span>
                            </div>
                            <input type="range" min="0" max="150" value={gap} onChange={(e) => {
                                const newGap = parseInt(e.target.value);
                                setGap(newGap);
                                if (activeLayoutCols) {
                                    setImages(prev => applyGridLayout(activeLayoutCols, newGap, prev));
                                }
                            }} style={{ width: '100%', accentColor: TOKENS.colors.primary, cursor: 'pointer' }} />
                        </div>
                        <p style={{ fontSize: '0.7rem', color: TOKENS.colors.textDim, marginTop: '0.75rem', lineHeight: 1.4 }}>Tip: Once photos are generated onto the Canvas, you can freely drag, resize, and rotate them!</p>
                    </div>
                    
                    <hr style={{ border: 'none', borderTop: `1px solid ${TOKENS.colors.border}` }} />

                    {/* Design Templates */}
                    <div>
                        <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, marginBottom: '1rem', fontWeight: '700', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                            <Palette size={14} /> Design Templates
                        </h3>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
                            {COLLAGE_TEMPLATES.map(t => (
                                <TemplatePreview 
                                    key={t.id} 
                                    template={t} 
                                    onClick={() => applyTemplate(t)}
                                    isActive={false}
                                />
                            ))}
                        </div>
                        {availablePhotos.length === 0 && (
                            <p style={{ fontSize: '0.7rem', color: '#EF4444', marginTop: '0.75rem', lineHeight: 1.4 }}>Add photos from the cluster below before applying a template.</p>
                        )}
                    </div>
                    
                    <hr style={{ border: 'none', borderTop: `1px solid ${TOKENS.colors.border}` }} />

                    {/* Cluster Photos */}
                    <div>
                        <h3 style={{ fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: TOKENS.colors.textDim, marginBottom: '1rem', fontWeight: '700' }}>Cluster Photos ({images.length}/{availablePhotos.length})</h3>
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.5rem' }}>
                            {availablePhotos.map(photo => {
                                const isAdded = images.some(img => img.id === photo.id);
                                return (
                                    <div 
                                        key={photo.id} 
                                        onClick={() => togglePhoto(photo)}
                                        style={{ 
                                            aspectRatio: '1', 
                                            borderRadius: '6px', 
                                            overflow: 'hidden', 
                                            cursor: 'pointer',
                                            border: isAdded ? `2px solid ${TOKENS.colors.primary}` : '2px solid transparent',
                                            opacity: isAdded ? 1 : 0.6,
                                            transition: 'all 0.1s',
                                            backgroundImage: `url(${photo.url})`,
                                            backgroundSize: 'cover',
                                            backgroundPosition: 'center',
                                            pointerEvents: 'auto'
                                        }} 
                                    />
                                );
                            })}
                        </div>
                    </div>
                </div>

                {/* Canvas Area wrapper */}
                <div ref={containerRef} style={{
                    flex: 1, backgroundColor: '#E2E8F0',
                    backgroundImage: 'radial-gradient(#CBD5E1 1px, transparent 1px)',
                    backgroundSize: '20px 20px', display: 'flex', alignItems: 'center', justifyContent: 'center',
                    position: 'relative', overflow: 'hidden'
                }}>
                    
                    {/* Visual Canvas Drop Shadow Box */}
                    <div style={{
                        width: CANVAS_WIDTH * scale, height: CANVAS_HEIGHT * scale,
                        boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.25)',
                        backgroundColor: 'white',
                        position: 'relative'
                    }}>
                        {/* React Konva Stage */}
                        <Stage
                            width={CANVAS_WIDTH}
                            height={CANVAS_HEIGHT}
                            onMouseDown={checkDeselect}
                            onTouchStart={checkDeselect}
                            ref={stageRef}
                            style={{ 
                                transform: `scale(${scale})`, 
                                transformOrigin: 'top left',
                                cursor: selectedId ? 'move' : 'default'
                            }}
                        >
                            <Layer>
                                {/* Fixed white paper background ensures transparent photos don't bleed visually */}
                                <Rect
                                    x={0}
                                    y={0}
                                    width={CANVAS_WIDTH}
                                    height={CANVAS_HEIGHT}
                                    fill="white"
                                />

                                {images.map((img, i) => {
                                    // Render text layers differently
                                    if (img.type === 'text') {
                                        return (
                                            <KonvaText
                                                key={img.id}
                                                x={img.x}
                                                y={img.y}
                                                text={img.text}
                                                fontSize={img.fontSize || 24}
                                                fontStyle={img.fontStyle || 'normal'}
                                                fill={img.fill || '#1E293B'}
                                                draggable
                                                rotation={img.rotation || 0}
                                                onClick={() => setSelectedId(img.id)}
                                                onTap={() => setSelectedId(img.id)}
                                                onDragEnd={(e) => {
                                                    const imgs = images.slice();
                                                    imgs[i] = { ...img, x: e.target.x(), y: e.target.y() };
                                                    setImages(imgs);
                                                }}
                                            />
                                        );
                                    }
                                    
                                    return (
                                        <URLImage
                                            key={img.id}
                                            imageElem={img}
                                            shapeProps={img}
                                            isSelected={img.id === selectedId}
                                            onSelect={() => setSelectedId(img.id)}
                                            onChange={(newAttrs) => {
                                                const imgs = images.slice();
                                                imgs[i] = newAttrs;
                                                setImages(imgs);
                                                setActiveLayoutCols(null);
                                            }}
                                        />
                                    );
                                })}
                            </Layer>
                        </Stage>
                    </div>

                    <div style={{ position: 'absolute', bottom: '2rem', right: '2rem', background: 'white', padding: '0.5rem 1rem', borderRadius: '30px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)', fontSize: '0.8rem', fontWeight: '600', color: TOKENS.colors.textDim, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        <Maximize size={15} color={TOKENS.colors.primary} /> 
                        Poster Size ({(CANVAS_WIDTH * scale).toFixed(0)} x {(CANVAS_HEIGHT * scale).toFixed(0)} display)
                    </div>
                </div>
            </div>
        </div>
    );
};

// Generic button styles helper
const btnStyle = (active) => ({
    padding: '0.6rem', background: active ? '#EEF2FF' : '#F8FAFC', color: active ? '#4F46E5' : '#64748B',
    border: `1px solid ${active ? '#C7D2FE' : '#E2E8F0'}`, borderRadius: '6px', fontSize: '0.8rem',
    fontWeight: '600', cursor: active ? 'pointer' : 'not-allowed', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '0.35rem'
});

const layoutBtnStyle = {
    padding: '1rem', background: 'white', border: '1px solid #E2E8F0', borderRadius: '8px',
    color: '#475569', fontSize: '0.8rem', fontWeight: '600', cursor: 'pointer', display: 'flex', flexDirection: 'column',
    alignItems: 'center', gap: '0.75rem'
};

export default CollageManager;

import React, { useState, useEffect, useRef, useCallback, forwardRef } from 'react';
import HTMLFlipBook from 'react-pageflip';
import { motion, AnimatePresence } from 'framer-motion';
import { X, ArrowLeft, ChevronLeft, ChevronRight, Loader2, Download, PackageOpen, ChevronDown, FileText, FileCode2 } from 'lucide-react';
import { saveAs } from 'file-saver';
import { jsPDF } from 'jspdf';

// Helper function to convert a Blob to Base64 (needed for standalone HTML inside img tags)
const blobToBase64 = (blob) => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
};

const generateCoverCanvasBase64 = (title, count) => {
    const canvas = document.createElement('canvas');
    const canvasWidth = 1260; // 210 * 6
    const canvasHeight = 1782; // 297 * 6
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
    const ctx = canvas.getContext('2d');
    
    const grad = ctx.createLinearGradient(0, 0, canvasWidth, canvasHeight);
    grad.addColorStop(0, '#1E293B');
    grad.addColorStop(1, '#0F172A');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);
    
    ctx.fillStyle = '#ffffff';
    ctx.textAlign = 'center';
    
    ctx.font = 'bold 80px sans-serif';
    ctx.fillText(title, canvasWidth / 2, canvasHeight / 2 - 50);
    
    ctx.fillStyle = 'rgba(255,255,255,0.2)';
    ctx.fillRect(canvasWidth / 2 - 200, canvasHeight / 2 + 50, 400, 4);
    
    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    ctx.font = 'bold 35px sans-serif';
    ctx.fillText(`${count} MEMORIES`, canvasWidth / 2, canvasHeight / 2 + 150);
    
    return canvas.toDataURL('image/jpeg', 0.8);
};

const generatePDFCanvasBase64 = (img, imgWidth, imgHeight, isCover) => {
    const canvas = document.createElement('canvas');
    const isLandscape = imgWidth > imgHeight;
    const canvasWidth = isLandscape ? 1782 : 1260;
    const canvasHeight = isLandscape ? 1260 : 1782;
    
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
    const ctx = canvas.getContext('2d');
    
    // Fill dark background like the webpage
    ctx.fillStyle = '#0F172A';
    ctx.fillRect(0, 0, canvasWidth, canvasHeight);
    
    if (isCover) {
        // Landscape (cover)
        const scale = Math.max(canvasWidth / imgWidth, canvasHeight / imgHeight);
        const drawW = imgWidth * scale;
        const drawH = imgHeight * scale;
        const drawX = (canvasWidth - drawW) / 2;
        const drawY = (canvasHeight - drawH) / 2;
        ctx.drawImage(img, drawX, drawY, drawW, drawH);
    } else {
        // Portrait (contain with ambient blur)
        ctx.save();
        ctx.filter = 'blur(40px) brightness(60%) saturate(120%)';
        const bgScale = Math.max(canvasWidth / imgWidth, canvasHeight / imgHeight) * 1.1;
        const bgW = imgWidth * bgScale;
        const bgH = imgHeight * bgScale;
        ctx.drawImage(img, (canvasWidth - bgW) / 2, (canvasHeight - bgH) / 2, bgW, bgH);
        ctx.restore();
        
        // Draw crisp image
        const scale = Math.min(canvasWidth / imgWidth, canvasHeight / imgHeight);
        const drawW = imgWidth * scale;
        const drawH = imgHeight * scale;
        const drawX = (canvasWidth - drawW) / 2;
        const drawY = (canvasHeight - drawH) / 2;
        
        ctx.save();
        ctx.shadowColor = 'rgba(0, 0, 0, 0.5)';
        ctx.shadowBlur = 40;
        ctx.fillRect(drawX, drawY, drawW, drawH); 
        ctx.restore();
        
        ctx.drawImage(img, drawX, drawY, drawW, drawH);
    }
    
    // Compress heavily to keep PDF small
    return {
        base64: canvas.toDataURL('image/jpeg', 0.6),
        isLandscape
    };
};

// ... (Helper function to generate offline vanilla HTML flipbook)
const generateOfflineFlipbookHTML = (photoData, eventName) => {
    const title = eventName || 'Photo Flipbook';
    
    // Generate page HTML strings
    let pagesHtml = '';
    
    // Cover Page
    pagesHtml += `
    <div class="page page-cover page-cover-top">
        <div class="page-content">
            <h2 style="font-size: 3rem; color: #fff; margin-bottom: 1rem; width: 100%; word-wrap: break-word;">${title}</h2>
            <div style="width: 100%; height: 2px; background: rgba(255,255,255,0.2); margin-bottom: 2rem;"></div>
            <p style="text-transform: uppercase; letter-spacing: 0.1em; color: rgba(255,255,255,0.5);">${photoData.length} Memories</p>
        </div>
    </div>
    <div class="page">
        <div class="page-content" style="background-color: #f1f5f9; display: flex; align-items: center; justify-content: center; color: #94a3b8;">
            <h2>Open to begin</h2>
        </div>
    </div>`;

    // Photo Pages using embedded base64
    photoData.forEach((data) => {
        pagesHtml += `
        <div class="page">
            <div class="page-content photo-page">
                <div class="ambient-bg" style="background-image: url('${data.base64}')"></div>
                <img src="${data.base64}" alt="Photo" class="photo-img" />
            </div>
        </div>`;
    });

    // Back Cover
    pagesHtml += `
    <div class="page page-cover page-cover-bottom">
        <div class="page-content">
            <h2>The End</h2>
        </div>
    </div>`;

    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${title}</title>
    <script src="https://cdn.jsdelivr.net/npm/page-flip/dist/js/page-flip.browser.js"></script>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        body {
            margin: 0;
            padding: 0;
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            background-color: #0F172A;
            background-image: radial-gradient(rgba(255, 255, 255, 0.1) 1.5px, transparent 1.5px);
            background-size: 32px 32px;
            font-family: 'Inter', sans-serif;
            overflow: hidden;
        }

        .flipbook-container {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            height: 100vh;
            padding: 40px;
            box-sizing: border-box;
        }

        .flip-book {
            box-shadow: 0 0 100px rgba(0,0,0,0.8), 0 0 0 1px rgba(255,255,255,0.05);
            border-radius: 4px;
        }

        .page {
            background-color: #fff;
            overflow: hidden;
            box-shadow: 0 0 20px rgba(0,0,0,0.2) inset;
        }

        .page-content {
            width: 100%;
            height: 100%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            position: relative;
        }

        .page-cover {
            background-color: #1E293B;
            background-image: linear-gradient(135deg, #1E293B 0%, #0F172A 100%);
            color: #fff;
            border-left: solid 1px rgba(255, 255, 255, 0.1);
            border-right: solid 1px rgba(0, 0, 0, 0.5);
        }

        .page-cover.page-cover-top { border-radius: 6px 4px 4px 6px; }
        .page-cover.page-cover-bottom { border-radius: 4px 6px 6px 4px; }
        
        .page-cover .page-content {
             padding: 40px;
             box-sizing: border-box;
        }

        .photo-page {
            background: #000;
        }

        .ambient-bg {
            position: absolute;
            inset: -40px;
            z-index: 1;
            background-position: center;
            background-size: cover;
            background-repeat: no-repeat;
            filter: blur(30px) brightness(0.6) saturate(1.2);
            transform: scale(1.1);
        }

        .photo-img {
            position: relative;
            z-index: 2;
            width: 100%;
            height: 100%;
            display: block;
            object-fit: contain;
            filter: drop-shadow(0 0 20px rgba(0,0,0,0.5));
        }

        /* Center spine shading */
        .page-content::after {
            content: '';
            position: absolute;
            top: 0; bottom: 0;
            width: 40px;
            z-index: 10;
            pointer-events: none;
        }
        .--left .page-content::after {
            right: 0;
            background: linear-gradient(to right, transparent, rgba(0,0,0,0.4));
        }
        .--right .page-content::after {
            left: 0;
            background: linear-gradient(to left, transparent, rgba(0,0,0,0.4));
        }

    </style>
</head>
<body>
    <div class="flipbook-container">
        <div id="flipbook" class="flip-book">
            ${pagesHtml}
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const flipBook = new St.PageFlip(
                document.getElementById('flipbook'),
                {
                    width: 500,
                    height: 650,
                    size: 'stretch',
                    minWidth: 315,
                    maxWidth: 600,
                    minHeight: 420,
                    maxHeight: 780,
                    showCover: true,
                    maxShadowOpacity: 0.5,
                    mobileScrollSupport: false,
                    drawShadow: true,
                }
            );
            
            flipBook.loadFromHTML(document.querySelectorAll('.page'));
        });
    </script>
</body>
</html>`;
};

/* ─── Page Component (forwardRef required by react-pageflip) ─── */
const Page = forwardRef(({ photo, index, total, type, eventName }, ref) => {

    /* Cover */
    if (type === 'cover') {
        return (
            <div ref={ref} style={{ width: '100%', height: '100%', background: 'transparent' }}>
                <div style={{
                    width: '100%', height: '100%',
                    background: 'linear-gradient(135deg, #0F172A 0%, #1E293B 50%, #020617 100%)',
                    display: 'flex', flexDirection: 'column',
                    alignItems: 'center', justifyContent: 'center',
                    position: 'relative', overflow: 'hidden',
                }}>
                    <h1 style={{
                        fontSize: '1.5rem', fontWeight: '700', color: 'rgba(255,255,255,0.7)',
                        textAlign: 'center', margin: 0, letterSpacing: '-0.01em',
                        lineHeight: '1.5', width: '100%',
                    }}>Your Moments in<br /><span style={{ color: 'rgba(255,255,255,0.95)', fontWeight: '800' }}>{eventName || 'This Event'}</span></h1>
                </div>
            </div>
        );
    }

    /* Back Cover or Missing Photo string fallback */
    const photoUrl = photo ? (typeof photo === 'string' ? photo : (photo.photo_url || photo.url)) : null;

    if (type === 'back' || (!photoUrl && type === 'photo')) {
        return (
            <div ref={ref} style={{ width: '100%', height: '100%', background: 'transparent' }}>
                <div style={{
                    width: '100%', height: '100%',
                    background: 'linear-gradient(135deg, #020617 0%, #1E293B 50%, #0F172A 100%)',
                    display: 'flex', flexDirection: 'column',
                    alignItems: 'center', justifyContent: 'center',
                }}>
                    <div style={{
                        fontSize: '0.55rem', letterSpacing: '0.3em', textTransform: 'uppercase',
                        color: 'rgba(255,255,255,0.25)', fontWeight: '600', marginBottom: '0.5rem',
                    }}>The End</div>
                    <h2 style={{
                        fontSize: '1.2rem', fontWeight: '700', color: 'rgba(255,255,255,0.6)',
                        margin: 0,
                    }}>Thank You</h2>
                </div>
            </div>
        );
    }

    // Photo object logic (smart crop with bbox)
    const bbox = photo?.bbox; 
    let objectPosition = 'center center';
    let [imgWidth, imgHeight] = [0, 0];
    
    if (bbox && bbox.length === 4 && typeof photo !== 'string') {
        const [x, y, w, h] = bbox;
        if (w > 0) {
            const faceCenterX = x + (w / 2);
            const faceCenterY = y + (h / 2);
            
            if (w <= 1 && h <= 1) {
                 const posX = Math.max(0, Math.min(100, faceCenterX * 100));
                 // Bias slightly above exact center to include hair/top of head comfortably
                 const posY = Math.max(0, Math.min(100, Math.max(0, faceCenterY * 100 - 10)));
                 objectPosition = `${posX}% ${posY}%`;
            } 
        }
    }
    
    // Attempt to read explicit dimensions if provided by API
    if (photo && typeof photo !== 'string' && photo.photo_width && photo.photo_height) {
        imgWidth = photo.photo_width;
        imgHeight = photo.photo_height;
    }

    // Determine strategy: If tall (portrait/square) use contain with blur background. If wide (landscape), use cover.
    // Fallback to contain if we don't know dimensions, to be safe.
    const isLandscape = imgWidth > imgHeight;
    const objectFitMode = (imgWidth && imgHeight) ? (isLandscape ? 'cover' : 'contain') : 'contain';

    /* Photo Page — edge-to-edge */
    return (
        <div ref={ref} style={{
            width: '100%', height: '100%',
            background: '#0a0a0a',
            position: 'relative', overflow: 'hidden',
            boxShadow: 'inset 0 0 0 1px rgba(255,255,255,0.05), inset 0 0 20px rgba(0,0,0,0.5)',
        }}>
            {/* Subtle inner shadow overlay for depth */}
            <div style={{
                position: 'absolute', inset: 0, zIndex: 5, pointerEvents: 'none',
                background: 'linear-gradient(90deg, rgba(0,0,0,0.6) 0%, transparent 10%, transparent 90%, rgba(0,0,0,0.6) 100%)',
            }} />
            
            {/* Ambient Blurred Background (visible mostly for 'contain' tall photos) */}
            <div style={{
                position: 'absolute', inset: -40, zIndex: 1, // Slightly oversized to hide blur edges
                background: `url(${photoUrl}) center/cover no-repeat`,
                filter: 'blur(30px) brightness(0.6) saturate(1.2)',
                transform: 'scale(1.1)', // help hide hard edges
            }} />
            
            <img
                src={photoUrl}
                alt={`Photo ${index + 1}`}
                style={{
                    position: 'relative', zIndex: 2,
                    width: '100%', height: '100%',
                    objectFit: objectFitMode,
                    objectPosition: objectPosition,
                    display: 'block',
                    boxShadow: objectFitMode === 'contain' ? '0 0 40px rgba(0,0,0,0.5)' : 'none',
                }}
                onLoad={(e) => {
                    // Fallback evaluation if photo dimensions weren't strictly provided by API
                    if (!imgWidth || !imgHeight) {
                        const { naturalWidth, naturalHeight } = e.target;
                        if (naturalHeight >= naturalWidth) {
                            e.target.style.objectFit = 'contain';
                            e.target.style.boxShadow = '0 0 40px rgba(0,0,0,0.5)';
                        } else {
                            e.target.style.objectFit = 'cover';
                            e.target.style.boxShadow = 'none';
                        }
                    }
                }}
            />
            {/* Subtle page number at bottom */}
            <div style={{
                position: 'absolute', bottom: '0.8rem', right: '1rem', zIndex: 10,
                fontSize: '0.65rem', color: 'rgba(255,255,255,0.6)',
                fontWeight: '600', letterSpacing: '0.08em',
                textShadow: '0 2px 8px rgba(0,0,0,0.9), 0 0 2px rgba(0,0,0,0.8)',
                pointerEvents: 'none',
                background: 'rgba(0,0,0,0.3)', padding: '4px 8px',
                borderRadius: '4px', backdropFilter: 'blur(4px)',
                border: '1px solid rgba(255,255,255,0.1)',
            }}>
                {index + 1} / {total}
            </div>
        </div>
    );
});

Page.displayName = 'Page';

/* ─── Main Flipbook Manager ─── */
const FlipbookManager = ({ initialPhotos = [], onClose, backLabel = "Back", eventName = "" }) => {
    const [photos, setPhotos] = useState([]);
    const bookRef = useRef(null);
    const [currentPage, setCurrentPage] = useState(0);
    const [totalPages, setTotalPages] = useState(0);
    const [isReady, setIsReady] = useState(false);
    const [dimensions, setDimensions] = useState({ width: 500, height: 400 });
    const [isExporting, setIsExporting] = useState(false);
    const [exportFormat, setExportFormat] = useState(null); // 'html' or 'pdf'
    const [showExportMenu, setShowExportMenu] = useState(false);
    const dropdownRef = useRef(null);

    useEffect(() => {
        const filtered = initialPhotos.filter(p => !!p);
        setPhotos(filtered);
        setTotalPages(filtered.length + 2);
    }, [initialPhotos]);

    /* Calculate landscape book size to fill screen */
    useEffect(() => {
        const calc = () => {
            const topBar = 48;
            const bottomBar = 40;
            const vPad = 20;
            const hPad = 140; // room for nav arrows

            const availH = window.innerHeight - topBar - bottomBar - vPad;
            const availW = window.innerWidth - hPad;

            // Landscape: each page is wider than tall (4:3 per page)
            // The book shows one page at a time in portrait mode
            // We want landscape ratio ~4:3 per single page
            const pageRatio = 4 / 3; // width / height
            let pageH = availH;
            let pageW = pageH * pageRatio;

            // If the single page is too wide for half the screen, constrain
            if (pageW > availW / 1.2) {
                pageW = availW / 1.2;
                pageH = pageW / pageRatio;
            }

            pageW = Math.max(300, Math.min(pageW, 900));
            pageH = Math.max(220, Math.min(pageH, 700));

            setDimensions({ width: Math.round(pageW), height: Math.round(pageH) });
        };

        calc();
        window.addEventListener('resize', calc);
        return () => window.removeEventListener('resize', calc);
    }, []);

    const onFlip = useCallback((e) => setCurrentPage(e.data), []);
    const onInit = useCallback(() => setIsReady(true), []);
    const goNext = () => bookRef.current?.pageFlip()?.flipNext();
    const goPrev = () => bookRef.current?.pageFlip()?.flipPrev();

    /* Keyboard */
    useEffect(() => {
        const handleKey = (e) => {
            if (e.key === 'ArrowRight') goNext();
            else if (e.key === 'ArrowLeft') goPrev();
            else if (e.key === 'Escape') onClose?.();
        };
        window.addEventListener('keydown', handleKey);
        return () => window.removeEventListener('keydown', handleKey);
    }, [onClose]);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setShowExportMenu(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const progress = totalPages > 1 ? currentPage / (totalPages - 1) : 0;

    // Helper to safely fetch images avoiding CORS blocks on S3/Cloudfront
    const fetchImageSafe = async (imageUrl) => {
        // Bypass browser cache which may have stored the image without CORS headers from a standard <img> tag
        const cacheBustedUrl = imageUrl.includes('?') 
            ? `${imageUrl}&cors_t=${Date.now()}` 
            : `${imageUrl}?cors_t=${Date.now()}`;
            
        try {
            const res = await fetch(cacheBustedUrl, { mode: 'cors' });
            if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
            return await res.blob();
        } catch (e) {
            console.warn('Direct fetch failed (likely CORS), trying primary proxy for:', imageUrl);
            try {
                // Primary proxy
                const proxyUrl1 = `https://corsproxy.io/?url=${encodeURIComponent(imageUrl)}`;
                const res1 = await fetch(proxyUrl1);
                if (!res1.ok) throw new Error(`Proxy 1 HTTP error! status: ${res1.status}`);
                return await res1.blob();
            } catch (e2) {
                console.warn('Primary proxy failed, trying secondary proxy for:', imageUrl);
                // Secondary proxy
                const proxyUrl2 = `https://api.allorigins.win/raw?url=${encodeURIComponent(imageUrl)}`;
                const res2 = await fetch(proxyUrl2);
                if (!res2.ok) throw new Error(`Proxy 2 HTTP error! status: ${res2.status}`);
                return await res2.blob();
            }
        }
    };



    const fetchAllPhotosAsBlobs = async () => {
        const blobsData = [];
        
        // Fetch sequentially to avoid rate-limiting from free public proxies
        for (let index = 0; index < photos.length; index++) {
            const photo = photos[index];
            const url = typeof photo === 'string' ? photo : (photo.photo_url || photo.url);
            if (!url) continue;
            
            try {
                const blob = await fetchImageSafe(url);
                // Get natural dimensions from image to know if it's landscape/portrait for PDF
                const img = new Image();
                img.src = window.URL.createObjectURL(blob);
                await new Promise(resolve => { img.onload = resolve; });
                
                blobsData.push({
                    blob,
                    width: img.naturalWidth,
                    height: img.naturalHeight,
                    index
                });
                
                window.URL.revokeObjectURL(img.src);
                
                // Small delay to be polite to proxies
                await new Promise(r => setTimeout(r, 100));
            } catch (e) {
                console.error(`Failed to fetch photo ${index + 1}:`, e);
            }
        }

        return blobsData;
    };

    const handleExportHTML = async () => {
        if (isExporting || photos.length === 0) return;
        setIsExporting(true);
        setExportFormat('html');
        setShowExportMenu(false);

        try {
            const baseName = eventName ? `${eventName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}` : 'flipbook';
            
            const blobsData = await fetchAllPhotosAsBlobs();
            if (blobsData.length === 0) throw new Error("No images could be downloaded.");

            // Convert to base64
            const photoData = [];
            for (const item of blobsData) {
                const base64 = await blobToBase64(item.blob);
                photoData.push({ base64 });
            }
            
            // Generate and inject offline HTML index
            const offlineHtml = generateOfflineFlipbookHTML(photoData, eventName);
            const blob = new Blob([offlineHtml], { type: "text/html;charset=utf-8" });
            saveAs(blob, `${baseName}_interactive.html`);
            
        } catch (error) {
            console.error('Error creating HTML export:', error);
            alert('Failed to generate interactive HTML. Please try downloading individual photos.');
        } finally {
            setIsExporting(false);
            setExportFormat(null);
        }
    };

    const handleExportPDF = async () => {
        if (isExporting || photos.length === 0) return;
        setIsExporting(true);
        setExportFormat('pdf');
        setShowExportMenu(false);

        try {
            const baseName = eventName ? `${eventName.replace(/[^a-z0-9]/gi, '_').toLowerCase()}` : 'album';
            
            const blobsData = await fetchAllPhotosAsBlobs();
            if (blobsData.length === 0) throw new Error("No images could be downloaded.");

            const pdf = new jsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
            
            // Generate Cover Page to match UI
            const coverBase64 = generateCoverCanvasBase64(eventName || 'Photo Album', blobsData.length);
            pdf.addImage(coverBase64, 'JPEG', 0, 0, 210, 297, undefined, 'FAST');
            
            for (let i = 0; i < blobsData.length; i++) {
                const item = blobsData[i];
                
                // Create temp image to draw on canvas
                const img = new Image();
                img.src = window.URL.createObjectURL(item.blob);
                await new Promise(resolve => { img.onload = resolve; });
                
                // If width > height, use 'cover' logic, else use 'contain' with blur logic
                const shouldCover = item.width > item.height;
                
                const { base64, isLandscape } = generatePDFCanvasBase64(img, item.width, item.height, shouldCover);
                window.URL.revokeObjectURL(img.src);
                
                const pdfOrientation = isLandscape ? 'l' : 'p';
                const pageWidth = isLandscape ? 297 : 210;
                const pageHeight = isLandscape ? 210 : 297;
                
                pdf.addPage('a4', pdfOrientation);
                // Canvas is exactly identical ratio to A4 (1920x1080 / 1080x1920 matches perfectly)
                pdf.addImage(base64, 'JPEG', 0, 0, pageWidth, pageHeight, undefined, 'FAST');
            }
            
            pdf.save(`${baseName}_photos.pdf`);
            
        } catch (error) {
            console.error('Error creating PDF export:', error);
            alert('Failed to generate PDF album. Please try downloading individual photos.');
        } finally {
            setIsExporting(false);
            setExportFormat(null);
        }
    };

    /* Loading */
    if (photos.length === 0) {
        return (
            <div style={{
                position: 'fixed', inset: 0, zIndex: 2000,
                background: '#000', display: 'flex', alignItems: 'center', justifyContent: 'center',
            }}>
                <Loader2 size={36} color="#6366F1" style={{ animation: 'flipbook-spin 1.5s linear infinite' }} />
                    <p style={{ color: '#94A3B8', marginTop: '1rem', fontSize: '0.9rem' }}>Loading your moments…</p>
            </div>
        );
    }

    return (
        <div style={{
            position: 'fixed', inset: 0, zIndex: 2000,
            background: '#020617', // Deeper base background
            display: 'flex', flexDirection: 'column',
            fontFamily: '"Inter", -apple-system, sans-serif',
            color: 'white', overflow: 'hidden',
        }}>
            
            {/* Cinematic background ambiance */}
            <div style={{
                position: 'absolute', inset: 0, pointerEvents: 'none',
                background: 'radial-gradient(circle at 50% 50%, rgba(99,102,241,0.08) 0%, rgba(0,0,0,0) 60%)',
                opacity: 0.8,
            }} />

            {/* ═══ Minimal top bar ═══ */}
            <div style={{
                height: '48px', flexShrink: 0,
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                padding: '0 1.25rem',
                background: 'rgba(0,0,0,0.6)',
                backdropFilter: 'blur(12px)',
                borderBottom: '1px solid rgba(255,255,255,0.08)',
                zIndex: 10,
            }}>
                <div style={{ flex: 1, display: 'flex', justifyContent: 'flex-start' }}>
                    <button
                        onClick={onClose}
                        style={{
                            background: 'rgba(255,255,255,0.08)', border: '1px solid rgba(255,255,255,0.1)',
                            color: 'rgba(255,255,255,0.7)', cursor: 'pointer',
                            display: 'flex', alignItems: 'center', gap: '0.35rem',
                            fontSize: '0.82rem', fontWeight: '600',
                            padding: '0.35rem 0.8rem', borderRadius: '6px',
                            transition: 'all 0.2s',
                        }}
                        onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.15)'; e.currentTarget.style.color = 'white'; }}
                        onMouseLeave={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.08)'; e.currentTarget.style.color = 'rgba(255,255,255,0.7)'; }}
                    >
                        <ArrowLeft size={15} /> {backLabel}
                    </button>
                </div>

                {/* Progress */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', flex: 1, justifyContent: 'center' }}>
                    <span style={{
                        fontSize: '0.75rem', color: 'rgba(255,255,255,0.4)',
                        fontWeight: '500', fontVariantNumeric: 'tabular-nums',
                    }}>
                        {currentPage + 1} / {totalPages}
                    </span>
                    <div style={{
                        width: '100px', height: '2px', borderRadius: '1px',
                        background: 'rgba(255,255,255,0.1)', overflow: 'hidden',
                    }}>
                        <div style={{
                            width: `${progress * 100}%`, height: '100%',
                            background: 'linear-gradient(90deg, #6366F1, #818CF8)',
                            transition: 'width 0.4s ease',
                            borderRadius: '1px',
                        }} />
                    </div>
                </div>

                {/* Right side actions */}
                <div style={{ flex: 1, display: 'flex', justifyContent: 'flex-end', alignItems: 'center', gap: '0.5rem' }}>
                    
                    {/* Export Dropdown Container */}
                    <div style={{ position: 'relative' }} ref={dropdownRef}>
                        <button
                            onClick={() => setShowExportMenu(!showExportMenu)}
                            disabled={isExporting || photos.length === 0}
                            style={{
                                background: 'rgba(99,102,241,0.15)', border: '1px solid rgba(99,102,241,0.3)',
                                color: '#e0e7ff', cursor: isExporting ? 'progress' : 'pointer', padding: '0.35rem 0.6rem 0.35rem 0.8rem', borderRadius: '6px',
                                display: 'flex', alignItems: 'center', gap: '0.35rem', transition: 'all 0.2s',
                                fontSize: '0.82rem', fontWeight: '600',
                                opacity: (isExporting || photos.length === 0) ? 0.6 : 1
                            }}
                            onMouseEnter={e => { if (!isExporting && !showExportMenu) { e.currentTarget.style.background = 'rgba(99,102,241,0.25)'; e.currentTarget.style.color = '#fff'; } }}
                            onMouseLeave={e => { if (!isExporting && !showExportMenu) { e.currentTarget.style.background = 'rgba(99,102,241,0.15)'; e.currentTarget.style.color = '#e0e7ff'; } }}
                        >
                            {isExporting ? <Loader2 size={15} className="animate-spin" /> : <PackageOpen size={15} />}
                            {isExporting ? `Exporting ${exportFormat?.toUpperCase()}...` : 'Export Album'}
                            <ChevronDown size={14} style={{ marginLeft: '4px', transform: showExportMenu ? 'rotate(180deg)' : 'none', transition: 'transform 0.2s' }} />
                        </button>

                        {/* Dropdown Menu */}
                        {showExportMenu && !isExporting && (
                            <div style={{
                                position: 'absolute', top: 'calc(100% + 8px)', right: 0,
                                background: 'rgba(15,23,42,0.95)',
                                backdropFilter: 'blur(16px)',
                                border: '1px solid rgba(255,255,255,0.1)',
                                borderRadius: '8px',
                                padding: '0.5rem',
                                minWidth: '200px',
                                boxShadow: '0 10px 25px -5px rgba(0,0,0,0.5), 0 8px 10px -6px rgba(0,0,0,0.3)',
                                zIndex: 50,
                                display: 'flex', flexDirection: 'column', gap: '4px'
                            }}>
                                <button
                                    onClick={handleExportPDF}
                                    style={{
                                        width: '100%', display: 'flex', alignItems: 'center', gap: '0.75rem',
                                        padding: '0.6rem 0.75rem', background: 'transparent',
                                        border: 'none', borderRadius: '4px', color: '#f1f5f9',
                                        cursor: 'pointer', textAlign: 'left',
                                        fontSize: '0.85rem', fontWeight: '500', transition: 'background 0.2s'
                                    }}
                                    onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.08)'}
                                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                                >
                                    <FileText size={16} color="#ef4444" />
