        { id: 'EMP002', name: 'Sarah Johnson', time: '09:02 AM', type: 'Check-in', location: 'Side Gate' },
        { id: 'EMP003', name: 'Mike Chen', time: '08:30 AM', type: 'Check-in', location: 'Main Entrance' },
