import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import '../landing.css';
import heroImage from '../assets/hero-abstract.jpg';
import HeroBackground from '../components/landing/HeroBackground';
import TypingText from '../components/TypingText';
import ScrambleText from '../components/ScrambleText';
import FocusText from '../components/FocusText';

// ScrollReveal component
function ScrollReveal({ children, className = "", delay = 0 }) {
    const ref = useRef(null);
    const [isVisible, setIsVisible] = useState(false);

    useEffect(() => {
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    setTimeout(() => setIsVisible(true), delay);
                    observer.unobserve(entry.target);
                }
            },
            { threshold: 0.1, rootMargin: "0px 0px -50px 0px" }
        );

        if (ref.current) observer.observe(ref.current);
        return () => observer.disconnect();
    }, [delay]);

    return (
        <div
            ref={ref}
            style={{
                transition: 'all 0.7s ease',
                opacity: isVisible ? 1 : 0,
                transform: isVisible ? 'translateY(0)' : 'translateY(2rem)'
            }}
            className={className}
        >
            {children}
        </div>
    );
}

// Features data
const features = [
    { number: "01", title: "Language Models", description: "State-of-the-art LLM integrations with OpenAI, Anthropic, and open-source alternatives. Fine-tuning pipelines included." },
    { number: "02", title: "Computer Vision", description: "Object detection, image segmentation, and video analysis. Pre-trained models ready for production deployment." },
    { number: "03", title: "Multimodal AI", description: "Combine text, image, audio, and video processing in unified pipelines. Cross-modal reasoning out of the box." },
    { number: "04", title: "Edge Deployment", description: "Optimized inference for edge devices. Quantization, pruning, and ONNX export with a single command." },
];

// Frameworks data
// Supported Models data
const frameworks = [
    { name: "Face Recognition", category: "Biometrics" },
    { name: "Face Clustering", category: "Unsupervised" },
    { name: "Object Detection", category: "Computer Vision" },
    { name: "Terrorism Detection", category: "Security" },
    { name: "Exam Cheating", category: "Education" },
    { name: "Emotion Recognition", category: "Behavioral" },
    { name: "Weapon Detection", category: "Safety" },
    { name: "Crowd Analytics", category: "Surveillance" },
];

// Neural Particle Effect Component
function NeuralParticles() {
    const canvasRef = useRef(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d');
        let animationFrameId;
        let particles = [];
        const particleCount = 40;
        const connectionDistance = 100;

        // Resize canvas
        const resize = () => {
            const parent = canvas.parentElement;
            if (parent) {
                canvas.width = parent.clientWidth;
                canvas.height = parent.clientHeight;
            }
        };

        window.addEventListener('resize', resize);
        resize();

        // Particle class
        class Particle {
            constructor() {
                this.x = Math.random() * canvas.width;
                this.y = Math.random() * canvas.height;
                this.vx = (Math.random() - 0.5) * 0.5;
                this.vy = (Math.random() - 0.5) * 0.5;
                this.size = Math.random() * 2 + 1;
            }

            update() {
                this.x += this.vx;
                this.y += this.vy;

                // Bounce off edges
                if (this.x < 0 || this.x > canvas.width) this.vx *= -1;
                if (this.y < 0 || this.y > canvas.height) this.vy *= -1;
            }

            draw() {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; // Dark particles
                ctx.fill();
            }
        }

        // Initialize particles
        for (let i = 0; i < particleCount; i++) {
            particles.push(new Particle());
        }

        // Animation loop
        const animate = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw connections
            ctx.strokeStyle = 'rgba(54, 212, 6, 0.91)'; // Cyan connections
            ctx.lineWidth = 1;

            for (let i = 0; i < particles.length; i++) {
                for (let j = i + 1; j < particles.length; j++) {
                    const dx = particles[i].x - particles[j].x;
                    const dy = particles[i].y - particles[j].y;
                    const distance = Math.sqrt(dx * dx + dy * dy);

                    if (distance < connectionDistance) {
                        ctx.beginPath();
                        ctx.moveTo(particles[i].x, particles[i].y);
                        ctx.lineTo(particles[j].x, particles[j].y);
                        ctx.stroke();
                    }
                }
            }

            // Update and draw particles
            particles.forEach(p => {
                p.update();
                p.draw();

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                ctx.fillStyle = 'rgba(0, 158, 197, 1)'; // Cyan particles
                ctx.fill();
            });

            animationFrameId = requestAnimationFrame(animate);
        };

        animate();

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <canvas
            ref={canvasRef}
            className="neural-particles"
            style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                pointerEvents: 'none',
                zIndex: 10
            }}
        />
    );
}

