                left: '50%',
                transform: 'translateX(-50%)',
                width: '120%',
                height: '600px',
                background: 'radial-gradient(50% 50% at 50% 50%, rgba(99, 102, 241, 0.15) 0%, transparent 100%)',
                pointerEvents: 'none',
                zIndex: 0
            }} />

            {/* Secondary Bottom-Right Glow (Soft Violet) */}
            <div style={{
                position: 'absolute',
                bottom: '-10%',
                right: '-10%',
                width: '800px',
                height: '800px',
                background: 'radial-gradient(50% 50% at 50% 50%, rgba(139, 92, 246, 0.1) 0%, transparent 100%)',
                pointerEvents: 'none',
                zIndex: 0
            }} />
            <div style={{
                flex: 1,
                display: 'flex',
                flexDirection: 'column',
                padding: '90px 2rem 2rem', // Added top padding for fixed navbar
                overflowY: 'auto', /* Scroll internally */
                maxWidth: '100%',
                position: 'relative',
                zIndex: 1
            }}>

                {/* 1. Sticky Header Bar */}
                <header style={{
                    position: 'sticky',
                    top: 0,
                    zIndex: 10,
                    display: 'flex',
                    flexWrap: 'wrap',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: '1rem',
                    marginBottom: '1.5rem',
                    backgroundColor: '#F8FAFC', /* Match page bg to avoid transparency issues */
                    backgroundImage: 'radial-gradient(#CBD5E1 1.5px, transparent 1.5px)', /* Match pattern */
                    backgroundSize: '24px 24px',
                    padding: '0.75rem 1.25rem',
                    borderRadius: '12px',
                    border: '1px solid #E2E8F0',
                    boxShadow: '0 4px 6px -1px rgba(0,0,0,0.02)'
                }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
                        <div>
                            <h1 style={{
                                fontSize: '1.25rem',
                                fontWeight: '700',
                                color: '#06bb15ff',
                                lineHeight: 1.2,
                                margin: 0
                            }}>
                                My Events
                            </h1>
                            <p style={{ color: '#64748B', fontSize: '0.8rem', margin: 0 }}>
