                                            border: 'none',
                                            cursor: 'pointer',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            transition: 'all 0.2s',
                                            color: '#EF4444',
                                            zIndex: 10
                                        }}
                                        title="Delete Event"
                                        onMouseOver={(e) => { e.currentTarget.style.backgroundColor = '#FEE2E2'; e.currentTarget.style.transform = 'scale(1.1)'; }}
                                        onMouseOut={(e) => { e.currentTarget.style.backgroundColor = 'rgba(255, 255, 255, 0.9)'; e.currentTarget.style.transform = 'scale(1)'; }}
                                    >
                                        <Trash2 size={14} strokeWidth={2.5} />
                                    </button>
                                </div>

                                <div style={{ padding: '0.85rem', display: 'flex', flexDirection: 'column', flex: 1 }}>
                                    <div style={{ marginBottom: 'auto' }}>
                                        <h3 style={{
                                            margin: '0 0 0.25rem 0',
                                            fontSize: '1rem',
                                            fontWeight: '700',
                                            color: '#0F172A',
                                            lineHeight: 1.3,
                                            overflow: 'hidden',
                                            display: '-webkit-box',
                                            WebkitLineClamp: 1,
                                            WebkitBoxOrient: 'vertical'
                                        }}>
                                            {event.name}
                                        </h3>
                                        <div style={{ fontFamily: 'var(--font-mono)', fontSize: '0.7rem', color: '#64748B', marginBottom: '0.25rem' }}>
                                            {event.event_id}
                                        </div>
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem', color: '#64748B', fontSize: '0.8rem' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                                                <Calendar size={12} />
                                                <span>{event.date}</span>
                                            </div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                                                <MapPin size={12} />
                                                <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{event.location}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div style={{
                                        marginTop: '0.75rem',
                                        paddingTop: '0.75rem',
                                        borderTop: '1px solid #F1F5F9',
                                        display: 'flex',
                                        justifyContent: 'space-between',
                                        alignItems: 'center',
                                        fontSize: '0.75rem'
                                    }}>
                                        <div style={{ display: 'flex', gap: '0.8rem' }}>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                                                <ImageIcon size={14} color="#64748B" />
                                                <span style={{ fontWeight: '700', color: '#334155' }}>{event.total_photos}</span>
                                            </div>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
                                                <Users size={14} color="#64748B" />
                                                <span style={{ fontWeight: '700', color: '#334155' }}>{event.attendees}</span>
                                            </div>
                                        </div>
                                        <div style={{ color: '#3B82F6', fontWeight: '600', fontSize: '0.7rem' }}>
                                            View
                                        </div>
                                    </div>
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                </div>
                {/* Confirmation Modal */}
                <ConfirmationModal
                    isOpen={isDeleteModalOpen}
                    onClose={cancelDeleteEvent}
                    onConfirm={confirmDeleteEvent}
                    title="Delete Event"
                    message={`Are you sure you want to delete "${eventToDelete?.name}"? This action cannot be undone and will delete all photos and data associated with this event.`}
                    type="danger"
                    confirmText="Delete Event"
                    isLoading={isDeleting}
                />
            </div>
        </div>
    );
};

