            )}

            {status === 'complete' && !isClustering && (
              <motion.div
                initial={{ opacity: 0, y: 10, scale: 0.95 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                style={{ marginTop: '2rem', paddingTop: '2rem', borderTop: '1px solid #E2E8F0' }}
              >
                <button
                  onClick={() => navigate(`/clusters/${selectedEventId}`)}
