                    padding: '1.25rem 3rem',
                    borderRadius: '16px',
                    color: 'white',
                    fontSize: '1.2rem',
                    fontWeight: '700',
                    cursor: 'pointer',
                    display: 'inline-flex', alignItems: 'center', gap: '0.75rem',
                    boxShadow: '0 10px 25px -5px rgba(79, 70, 229, 0.4)',
